from pathlib import Path
import re

app=Path('CaddieOS/App.js')
s=app.read_text()
if 'BUILD75_ROUND_FIT' not in s:
    s=s.replace('const BUILD74_REVIEW_FIXES=true;', 'const BUILD74_REVIEW_FIXES=true;\nconst BUILD75_ROUND_FIT=true;', 1)

round_new="""function Round({hole,setHole,units,gps,gpsLive,startLiveGPS,stopLiveGPS,targetDistances,wind,windDir,bag,tee,open,ask,listening,caddieText,scores,setScores,putts,setPutts,gir,setGir,fw,setFw,pen,setPen,coursePars,courseSI}){const i=Math.max(0,Math.min(17,n(hole)-1)),par=coursePars[i]||PARS[i],valid=targetDistances.center!==null&&targetDistances.center!==undefined,playing=valid?playsLike(targetDistances.center,wind,0,'Fairway',windDir,units):null,club=valid?nearestClub(playing,bag,units)[0]:'—',setA=(setter,a,v)=>setter(a.map((x,k)=>k===i?v:x)),step=(setter,a,d)=>setA(setter,a,String(Math.max(0,n(a[i])+d))),prev=()=>setHole(h=>String(Math.max(1,n(h)-1))),next=()=>setHole(h=>String(Math.min(18,n(h)+1))),MiniText=({children,style})=><Text maxFontSizeMultiplier={1} style={style}>{children}</Text>;return <><View style={{flexDirection:'row',gap:6,height:378}}><View style={{width:'44%'}}><View style={[s.holeMap,{height:'100%',backgroundColor:'#12382F'}]}><View style={{position:'absolute',top:45,width:100,height:275,backgroundColor:'#4C9461',borderRadius:48,transform:[{rotate:'3deg'}]}}/><View style={[s.mapGreen,{top:14,width:94,height:48}]}/><View style={[s.mapLine,{top:38,height:278}]}/><Text style={[s.mapFlag,{top:26}]}>⚑</Text><View style={[s.mapYou,{bottom:27,width:22,height:22,borderRadius:11}]}/><MiniText style={[s.mapYouText,{bottom:7}]}>YOU</MiniText><View style={{position:'absolute',top:70,left:6,backgroundColor:'rgba(4,19,30,.82)',borderRadius:6,padding:4}}><MiniText style={{color:C.white,fontWeight:'900',fontSize:10}}>{targetDistances.center??'—'} {units==='METRES'?'m':'yd'}</MiniText></View></View></View><View style={{flex:1,gap:4}}><View style={[s.panel,{marginBottom:0,padding:5,minHeight:45}]}><View style={{flexDirection:'row',alignItems:'center',justifyContent:'space-between'}}><TouchableOpacity style={{width:28,height:28,borderRadius:6,backgroundColor:C.navy,alignItems:'center',justifyContent:'center'}} onPress={prev}><MiniText style={{color:C.white,fontSize:19,fontWeight:'900'}}>‹</MiniText></TouchableOpacity><View style={s.center}><MiniText style={{fontSize:14,fontWeight:'900',color:C.navy}}>HOLE {i+1}</MiniText><MiniText style={{fontSize:8,fontWeight:'800',color:C.muted}}>PAR {par} · S.I. {courseSI?.[i]||STROKE_INDEX[i]}</MiniText></View><TouchableOpacity style={{width:28,height:28,borderRadius:6,backgroundColor:C.navy,alignItems:'center',justifyContent:'center'}} onPress={next}><MiniText style={{color:C.white,fontSize:19,fontWeight:'900'}}>›</MiniText></TouchableOpacity></View></View><View style={[s.panel,{marginBottom:0,padding:6,minHeight:64}]}><MiniText style={{fontSize:8,fontWeight:'900',color:C.navy}}>TO CENTRE</MiniText><MiniText style={{fontSize:21,fontWeight:'900',color:C.navy}}>{targetDistances.center??'—'} {units==='METRES'?'m':'yd'}</MiniText><MiniText style={{fontSize:8,color:C.muted}}>Front {targetDistances.front??'—'} · Back {targetDistances.back??'—'}</MiniText></View><View style={[s.panel,{marginBottom:0,padding:6,minHeight:112}]}><MiniText style={{fontSize:9,fontWeight:'900',color:C.navy}}>VOICE CADDIE</MiniText><TouchableOpacity onPress={ask} style={{height:34,borderWidth:1,borderColor:C.blue,borderRadius:17,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:5,marginVertical:4,backgroundColor:'#EEF4F7'}}><MiniText style={{fontSize:16}}>🎙</MiniText><MiniText style={{fontSize:9,fontWeight:'900',color:C.navy}}>{listening?'LISTENING…':'ASK CADDIE'}</MiniText></TouchableOpacity><MiniText numberOfLines={3} style={{fontSize:8.5,lineHeight:11,color:C.text,fontWeight:'700'}}>{caddieText}</MiniText></View><View style={[s.panel,{marginBottom:0,padding:6,minHeight:70}]}><MiniText style={{fontSize:8,fontWeight:'900',color:C.navy}}>RECOMMENDED CLUB</MiniText><MiniText style={{fontSize:18,fontWeight:'900',color:C.navy}}>{club}</MiniText><MiniText style={{fontSize:8,color:C.muted}}>{valid?`Playing ${playing} ${units==='METRES'?'m':'yd'}`:'Start live GPS'}</MiniText></View><View style={[s.panel,{marginBottom:0,padding:6,minHeight:48}]}><MiniText style={{fontSize:8,fontWeight:'900',color:C.navy}}>LAST SHOT</MiniText><MiniText style={{fontSize:8,color:C.muted}}>No shot recorded</MiniText></View></View></View><View style={{flexDirection:'row',gap:4,marginTop:5,height:62}}>{[['SCORE',scores,setScores],['PUTTS',putts,setPutts]].map(([label,a,setter])=><View key={label} style={{flex:1.15,borderWidth:1,borderColor:C.line,borderRadius:8,backgroundColor:C.panel,padding:4}}><MiniText style={{fontSize:8,fontWeight:'900',color:C.navy,textAlign:'center'}}>{label}</MiniText><View style={{flexDirection:'row',alignItems:'center',justifyContent:'space-around',flex:1}}><TouchableOpacity onPress={()=>step(setter,a,-1)}><MiniText style={{fontSize:20,fontWeight:'900',color:C.navy}}>−</MiniText></TouchableOpacity><MiniText style={{fontSize:19,fontWeight:'900',color:C.navy}}>{a[i]||0}</MiniText><TouchableOpacity onPress={()=>step(setter,a,1)}><MiniText style={{fontSize:20,fontWeight:'900',color:C.navy}}>+</MiniText></TouchableOpacity></View></View>)}{[['GIR',gir,setGir],['FW',fw,setFw],['PEN',pen,setPen]].map(([label,a,setter])=><TouchableOpacity key={label} style={[{flex:.75,borderWidth:1,borderColor:C.line,borderRadius:8,backgroundColor:C.panel,alignItems:'center',justifyContent:'center'},Boolean(a[i])&&s.toggleOn]} onPress={()=>label==='PEN'?setA(setter,a,n(a[i])?'':'1'):setA(setter,a,!a[i])}><MiniText style={{fontSize:8,fontWeight:'900',color:C.navy}}>{label}</MiniText><MiniText style={{fontSize:18,fontWeight:'900',color:C.navy}}>{Boolean(a[i])?'✓':'○'}</MiniText></TouchableOpacity>)}</View><View style={{flexDirection:'row',gap:5,marginTop:5}}><TouchableOpacity onPress={next} style={{flex:1,height:39,borderRadius:8,backgroundColor:C.blue,alignItems:'center',justifyContent:'center'}}><MiniText style={{fontSize:10,fontWeight:'900',color:C.white}}>NEXT HOLE</MiniText></TouchableOpacity><TouchableOpacity onPress={()=>open('SCORE')} style={{flex:1,height:39,borderRadius:8,borderWidth:1,borderColor:C.blue,alignItems:'center',justifyContent:'center'}}><MiniText style={{fontSize:9,fontWeight:'900',color:C.navy}}>VIEW SCORECARD</MiniText></TouchableOpacity></View><TouchableOpacity onPress={gpsLive?stopLiveGPS:startLiveGPS} style={{height:34,marginTop:5,borderRadius:8,borderWidth:1,borderColor:C.blue,alignItems:'center',justifyContent:'center'}}><MiniText style={{fontSize:9,fontWeight:'900',color:C.navy}}>{gpsLive?'STOP LIVE GPS':'START LIVE GPS'}</MiniText></TouchableOpacity></>}"""
s,nr=re.subn(r"function Round\(.*?\nfunction Caddie",round_new+'\nfunction Caddie',s,count=1,flags=re.S)
if nr!=1: raise SystemExit('Build 75 round replacement failed')
app.write_text(s)

g=Path('CaddieOS/android/app/build.gradle')
if g.exists():
    t=g.read_text()
    t=re.sub(r'versionCode\s+\d+','versionCode 75',t,count=1)
    t=re.sub(r'versionName\s+"[^"]+"','versionName "1.0.75"',t,count=1)
    g.write_text(t)
print('Build 75 compact round fit applied')
